insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L1', 'S2.2 The covalent model · Lesson 1: Covalent bonds, Lewis formulas, VSEPR shapes and polarity', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["1", "2", "3", "0", "1"], "tip": "Draw the Lewis formulas."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Linear", "Trigonal planar", "Trigonal pyramidal", "Bent (V-shaped)", "Tetrahedral"], "tip": "Count domains and lone pairs."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["lone pair", "two lone"], ["repel more", "greater repulsion", "push", "more repulsion"]], "tips": ["Lone pairs vs bonding pairs."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Polar", "Non-polar", "Polar", "Non-polar", "Polar"], "tip": "Do the dipoles cancel?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["linear", "symmetric"], ["cancel", "no net dipole", "opposite"]], "tips": ["Shape."]}]}, "models": {"1": [["Q1", "NH₃: 1 lone pair. H₂O: 2. N₂: triple bond, 3 shared pairs. CH₄: 0. NH₄⁺: 1 coordination bond."]], "2": [["Q2", "Linear; trigonal planar; trigonal pyramidal; bent; tetrahedral."], ["Q3", "Water has two lone pairs on oxygen [1]; lone pairs repel more strongly than bonding pairs, pushing the O–H bonds closer together [1]."]], "3": [["Q4", "H₂O, NH₃, CHCl₃: polar. CO₂, CCl₄: non-polar (symmetrical)."]], "4": [["Q5", "CO₂ is linear (symmetrical) [1], so the two C=O bond dipoles point in opposite directions and cancel, giving no net dipole [1]."]], "6": [["Exit ticket", "Trigonal pyramidal, about 107°."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8cdc260e-a335-53b5-a910-f3b8dcd4f87b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S2.2' limit 1), 'S2.2 The covalent model · Lesson 2: Covalent networks, intermolecular forces and chromatography', 'IB DP Chemistry · S2.2 The covalent model', '/chem-s22-lesson2/', 'CHEM-S22-L2', 19, 172 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L2', 'S2.2 The covalent model · Lesson 2: Covalent networks, intermolecular forces and chromatography', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Graphite", "Diamond", "Graphene", "Fullerene C₆₀", "Silicon dioxide"], "tip": "One each."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["London forces", "Dipole–dipole", "Hydrogen bonding", "Hydrogen bonding", "London forces", "Dipole–dipole"], "tip": "H on N, O, F?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["hydrogen bond"], ["h2s+dipole", "h2s+london", "sulfur", "weaker"], ["more energy", "stronger", "overcome"]], "tips": ["Type of IMF in each."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 3, "n": 3, "ans": ["0.75", "0.25", "Spot B"], "tip": "R_F = distance of spot ÷ distance of solvent."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["graphite+delocal", "graphite+three", "graphite+free electron"], ["diamond+four", "diamond+no free", "diamond+all"]], "tips": ["Bonds per carbon."]}]}, "models": {"1": [["Q1", "Graphite; diamond; graphene; fullerene; silicon dioxide."]], "2": [["Q2", "CH₄ and I₂: London. HCl and CH₃OCH₃: dipole–dipole. H₂O and NH₃: hydrogen bonding."], ["Q3", "Water molecules form hydrogen bonds because H is bonded to the very electronegative O [1]; H₂S has only dipole–dipole and London forces, which are weaker [1]; more energy is needed to overcome the hydrogen bonds in water [1]."]], "3": [["Q4", "A: 6.0/8.0 = 0.75; B: 2.0/8.0 = 0.25; B moves less, so it is more attracted to the stationary phase."]], "4": [["Q5", "In graphite each carbon bonds to three others, leaving one delocalized electron per atom that can move and carry charge [1]; in diamond all four outer electrons are used in bonds, so there are no free electrons [1]."]], "6": [["Exit ticket", "London < dipole–dipole < hydrogen bonding (for comparable molar mass)."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'cf920e34-dd10-50aa-b6f1-8deda5253758', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S2.2' limit 1), 'S2.2 The covalent model · Lesson 3 (HL): Resonance, benzene, expanded octets, formal charge, sigma and pi bonds, hybridization', 'IB DP Chemistry · S2.2 The covalent model', '/chem-s22-lesson3/', 'CHEM-S22-L3', 18, 173 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S22-L3', 'S2.2 The covalent model · Lesson 3 (HL): Resonance, benzene, expanded octets, formal charge, sigma and pi bonds, hybridization', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["same length", "equal length", "139"], ["hydrogenation", "substitution", "less exothermic", "stable", "addition"]], "tips": ["Bond lengths and reactivity/energy."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Trigonal bipyramidal", "Octahedral", "Seesaw", "Square planar", "Linear"], "tip": "Count domains; lone pairs go equatorial in 5-domain shapes."}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 2, "n": 2, "ans": ["0", "0"], "tip": "FC = V − N − B/2."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["sp³", "sp²", "sp", "5", "2"], "tip": "Count electron domains."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["sigma+head-on", "sigma+axis", "sigma+end-on", "sigma+between"], ["pi+sideways", "pi+above", "pi+p orbital", "pi+parallel"]], "tips": ["How the orbitals overlap."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["resonance", "delocal"], ["same", "equal", "spread", "intermediate", "1.33"]], "tips": ["Where is the double bond?"]}]}, "models": {"1": [["Q1", "All C–C bonds in benzene have the same length, intermediate between single and double [1]; benzene undergoes substitution rather than addition, and its enthalpy of hydrogenation is less exothermic than predicted, showing extra stability [1]."]], "2": [["Q2", "PCl₅ trigonal bipyramidal; SF₆ octahedral; SF₄ seesaw; XeF₄ square planar; XeF₂ linear."], ["Q3", "C: 4 − 0 − 8/2 = 0; O: 6 − 4 − 4/2 = 0. All zero, so this is the preferred structure."]], "3": [["Q4", "Ethane sp³; ethene sp²; ethyne sp; ethene 5 σ (4 C–H + 1 C–C); ethyne 2 π."], ["Q5", "A sigma bond forms by head-on overlap of orbitals, with electron density along the bond axis [1]; a pi bond forms by sideways overlap of p orbitals, with electron density above and below the axis [1]."]], "4": [["Q6", "The carbonate ion has resonance: the π electrons are delocalized over all three C–O bonds [1], so each bond is identical, intermediate between a single and double bond (bond order 1⅓) [1]."]], "6": [["Exit ticket", "sp²."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '85a29179-f76c-5941-8604-9ca7efa25d3d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S2.3' limit 1), 'S2.3 The metallic model · Lesson 1: Metallic bonding, properties of metals and bond strength', 'IB DP Chemistry · S2.3 The metallic model', '/chem-s23-lesson1/', 'CHEM-S23-L1', 6, 181 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S23-L1', 'S2.3 The metallic model · Lesson 1: Metallic bonding, properties of metals and bond strength', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["layers", "slide", "cations"], ["delocal", "electrons", "not broken", "still attract"]], "tips": ["Layers and electrons."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 2, "n": 2, "ans": ["Magnesium", "Lithium"], "tip": "Charge up, radius down."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["3+", "charge", "three electrons", "more delocalized"], ["smaller", "radius", "stronger"]], "tips": ["Charge and radius."]}]}, "models": {"1": [["Q1", "Layers of cations can slide over each other when a force is applied [1]; the delocalized electrons move with them, so the metallic bonding is not broken [1]."]], "2": [["Q2", "Magnesium (2+ ions, more delocalized electrons, smaller); lithium (smaller ions)."]], "3": [["Q3", "Aluminium forms 3+ ions and contributes three delocalized electrons per atom, compared with 1+ for sodium [1]; Al³⁺ is also smaller, so the electrostatic attraction is stronger [1]."]], "6": [["Exit ticket", "The electrostatic attraction between a lattice of cations and delocalized electrons."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5f69899e-636e-5b24-81e4-bf140f268eae', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S2.4' limit 1), 'S2.4 From models to materials · Lesson 1: The bonding triangle, alloys and addition polymers', 'IB DP Chemistry · S2.4 From models to materials', '/chem-s24-lesson1/', 'CHEM-S24-L1', 11, 191 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S24-L1', 'S2.4 From models to materials · Lesson 1: The bonding triangle, alloys and addition polymers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Mainly ionic", "Polar covalent", "Metallic"], "tip": "Δχ high → ionic."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["different size", "different-sized", "atoms"], ["disrupt", "layers", "slide", "harder to slide"]], "tips": ["Layers."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Poly(ethene)", "PVC (poly(chloroethene))", "Poly(propene)", "PTFE (poly(tetrafluoroethene))"], "tip": "Name the monomer."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["double bond", "c=c", "breaks"], ["join", "chain", "no other product", "only product"]], "tips": ["Bond broken; product."]}]}, "models": {"1": [["Q1", "NaCl: ionic; SiO₂: polar covalent; Al: metallic."]], "2": [["Q2", "The added atoms are a different size from the metal atoms [1], so they disrupt the regular layers and make it harder for layers to slide over each other [1]."]], "3": [["Q3", "Poly(ethene); PVC; poly(propene); PTFE."]], "4": [["Q4", "The C=C double bond in each monomer breaks [1], and monomers join to form a long chain with no other product formed [1]."]], "6": [["Exit ticket", "Electronegativity difference against average electronegativity."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '66801884-e098-5b7d-8cd1-279084949b1d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S2.4' limit 1), 'S2.4 From models to materials · Lesson 2 (HL): Transition metals'' delocalized d-electrons and condensation polymers', 'IB DP Chemistry · S2.4 From models to materials', '/chem-s24-lesson2/', 'CHEM-S24-L2', 8, 192 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S24-L2', 'S2.4 From models to materials · Lesson 2 (HL): Transition metals'' delocalized d-electrons and condensation polymers', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["d-electron", "d electrons", "3d"], ["more delocal", "stronger", "more electrons"]], "tips": ["Which electrons are delocalized?"]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Polyamide (amide link)", "Polyester (ester link)", "Addition polymer", "Polyamide (amide link)"], "tip": "What functional groups react?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["double bond", "c=c", "functional group"], ["small molecule", "water", "byproduct", "by-product", "only product"]], "tips": ["Monomers and products."]}]}, "models": {"1": [["Q1", "In iron, 3d electrons as well as 4s electrons are delocalized [1], so there are more delocalized electrons and stronger metallic bonding than in calcium [1]."]], "2": [["Q2", "Diamine + diacid: polyamide; diol + diacid: polyester; propene: addition; amino acids: polyamide."]], "3": [["Q3", "Addition polymers form from monomers with C=C double bonds, whereas condensation polymers form from monomers with two functional groups [1]; condensation releases a small molecule such as water, while addition polymerization forms only the polymer [1]."]], "6": [["Exit ticket", "Water."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd1f35d79-7ef7-5f43-b5d6-4514af808475', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S3.1' limit 1), 'S3.1 The periodic table: Classification of elements · Lesson 1: Periods, groups, blocks, periodic trends, oxides and oxidation states', 'IB DP Chemistry · S3.1 The periodic table: Classification of elements', '/chem-s31-lesson1/', 'CHEM-S31-L1', 21, 201 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S31-L1', 'S3.1 The periodic table: Classification of elements · Lesson 1: Periods, groups, blocks, periodic trends, oxides and oxidation states', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Period 3", "Group 16", "p-block"], "tip": "Outer level and valence electrons."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Na", "Cl", "K", "F⁻"], "tip": "Nuclear charge and shielding."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["nuclear charge", "protons", "more protons"], ["same", "shielding", "pulled", "attract", "closer"]], "tips": ["Charge vs shielding."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Basic oxide", "Amphoteric oxide", "Acidic oxide", "Reaction occurs", "No reaction"], "tip": "Metal oxide basic; non-metal oxide acidic; more reactive halogen displaces."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q5", "max": 5, "n": 5, "ans": ["+6", "+7", "+5", "+4", "−1"], "tip": "Sum to zero."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["further", "larger", "more shells", "shielding"], ["lost more easily", "lower ionization", "less attract", "weaker attraction"]], "tips": ["Outer electron."]}]}, "models": {"1": [["Q1", "Period 3 (n = 3), group 16 (6 valence electrons), p-block: sulfur."]], "2": [["Q2", "Na (fewer protons, same shell); Cl; K (outer electron further and more shielded); F⁻ (same electrons, fewer protons than Na⁺)."], ["Q3", "Nuclear charge increases across the period while electrons are added to the same energy level, so shielding stays about the same [1]; the outer electrons are pulled more strongly towards the nucleus, so the radius decreases [1]."]], "3": [["Q4", "MgO basic; Al₂O₃ amphoteric; SO₂ acidic; Cl₂ displaces I⁻ (reaction); I₂ cannot displace Cl⁻."]], "4": [["Q5", "S +6; Mn +7; N +5; C +4; O −1."]], "5": [["Q6", "Down the group the outer electron is further from the nucleus and more shielded [1], so it is less strongly attracted and lost more easily (lower ionization energy), making the metal more reactive [1]."]], "6": [["Exit ticket", "Increases, because nuclear charge increases while shielding stays similar, so bonding electrons are attracted more strongly."]]}, "labels": {"q2_1": "Q3", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '347dd2f6-8777-53b0-a641-c782855b645a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S3.1' limit 1), 'S3.1 The periodic table: Classification of elements · Lesson 2 (HL): Ionization energy discontinuities, transition elements, variable oxidation states and colour', 'IB DP Chemistry · S3.1 The periodic table: Classification of elements', '/chem-s31-lesson2/', 'CHEM-S31-L2', 17, 202 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S31-L2', 'S3.1 The periodic table: Classification of elements · Lesson 2 (HL): Ionization energy discontinuities, transition elements, variable oxidation states and colour', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["paired", "pair", "same orbital"], ["repulsion", "repel", "easier"]], "tips": ["Orbital diagrams."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Catalytic activity", "Variable oxidation states", "Coloured complexes", "Magnetic properties"], "tip": "One each."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["4s", "3d", "close in energy", "similar energy"], ["ionization energies", "gradual", "no large jump", "successive"]], "tips": ["Energy of 4s and 3d."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Colourless", "Coloured", "Orange", "Blue"], "tip": "d⁰/d¹⁰ colourless; opposite on the wheel."}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 3, "pts": [["ligand", "split", "splitting"], ["absorb", "promoted", "electron"], ["complementary", "orange", "red", "transmitted", "blue"]], "tips": ["Split, absorb, complementary."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["3p", "p sublevel", "p orbital"], ["higher energy", "shield", "further", "easier"]], "tips": ["Which sublevel?"]}]}, "models": {"1": [["Q1", "In sulfur the electron removed is from a 3p orbital containing a pair of electrons [1]; repulsion between the paired electrons makes it easier to remove than phosphorus''s unpaired electron [1]."]], "2": [["Q2", "Catalytic; variable oxidation states; coloured complexes; magnetic (paramagnetism)."], ["Q3", "The 4s and 3d sublevels are close in energy [1], so successive ionization energies increase gradually without a large jump, and different numbers of electrons can be lost [1]."]], "3": [["Q4", "Zn²⁺ colourless (d¹⁰); Ti³⁺ coloured; absorbs blue → orange; absorbs orange → blue."], ["Q5", "Water ligands split the 3d orbitals into two sets of different energy [1]; an electron absorbs visible light (in the orange-red region) and is promoted to the higher set [1]; the remaining light transmitted, the complementary colour, appears blue [1]."]], "4": [["Q6", "Aluminium''s outer electron is in a 3p orbital whereas magnesium''s is in 3s [1]; the 3p electron is higher in energy and partly shielded by the 3s electrons, so it is easier to remove [1]."]], "6": [["Exit ticket", "Zn and Zn²⁺ both have a full 3d¹⁰ sublevel, so it has no incomplete d sublevel."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q3", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f66ca062-89cc-5518-b2f2-dc876c3ae08a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S3.2' limit 1), 'S3.2 Functional groups: Classification of organic compounds · Lesson 1: Formulas, functional groups, homologous series, IUPAC naming and structural isomers', 'IB DP Chemistry · S3.2 Functional groups: Classification of organic compounds', '/chem-s32-lesson1/', 'CHEM-S32-L1', 23, 211 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S32-L1', 'S3.2 Functional groups: Classification of organic compounds · Lesson 1: Formulas, functional groups, homologous series, IUPAC naming and structural isomers', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Molecular", "Empirical", "Condensed structural", "Skeletal"], "tip": "What does each show?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 6, "n": 6, "ans": ["Alcohol", "Aldehyde", "Ketone", "Ester", "Amine", "Carboxylic acid"], "tip": "Look for the functional group."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["increase", "higher", "longer"], ["london", "dispersion", "electrons", "surface"]], "tips": ["IMFs."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 6, "n": 6, "ans": ["2-methylpropane", "propan-2-ol", "but-1-ene", "2-chlorobutane", "propanoic acid", "butan-2-one"], "tip": "Longest chain, lowest locant."}, {"kind": "choice", "id": "q3_1", "q": "Q5", "max": 3, "n": 3, "ans": ["Primary", "Secondary", "Tertiary"], "tip": "Count C atoms attached to the C–OH carbon."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["general formula", "same functional group"], ["ch2", "similar chemical", "trend", "gradual"]], "tips": ["Formula and properties."]}]}, "models": {"1": [["Q1", "C₂H₄O₂ molecular; CH₂O empirical; CH₃COOH condensed; skeletal drawing."]], "2": [["Q2", "Ethanol: alcohol; ethanal: aldehyde; propanone: ketone; methyl ethanoate: ester; methanamine: amine; methanoic acid: carboxylic acid."], ["Q3", "Boiling point increases as the chain gets longer [1] because larger molecules have more electrons and greater surface area, giving stronger London (dispersion) forces [1]."]], "3": [["Q4", "2-methylpropane; propan-2-ol; but-1-ene; 2-chlorobutane; propanoic acid; butan-2-one."], ["Q5", "Primary; secondary; tertiary."]], "4": [["Q6", "Members have the same functional group and general formula [1]; successive members differ by CH₂ and show a gradual trend in physical properties with similar chemical properties [1]."]], "6": [["Exit ticket", "Propan-1-ol; propan-2-ol."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '7fbf619d-b3d3-538a-9417-027e16e586ed', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'S3.2' limit 1), 'S3.2 Functional groups: Classification of organic compounds · Lesson 2 (HL): Stereoisomerism and spectroscopic identification (MS, IR, ¹H NMR)', 'IB DP Chemistry · S3.2 Functional groups: Classification of organic compounds', '/chem-s32-lesson2/', 'CHEM-S32-L2', 20, 212 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-S32-L2', 'S3.2 Functional groups: Classification of organic compounds · Lesson 2 (HL): Stereoisomerism and spectroscopic identification (MS, IR, ¹H NMR)', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Cis–trans", "Optical", "Neither", "Optical", "Neither"], "tip": "C=C with two different groups each end? C with four different groups?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["O–H (alcohol)", "C=O", "O–H (carboxylic acid)", "CH₃⁺", "COOH⁺"], "tip": "Use the data booklet ranges."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["3", "3:2:1", "Triplet", "Quartet", "Singlet"], "tip": "n + 1 rule."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["same environment", "equivalent", "identical", "symmetr"], ["singlet", "no adjacent", "no neighbouring"]], "tips": ["Symmetry; neighbours."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["c=o", "carbonyl", "1720"], ["no o–h", "no oh", "not alcohol", "not acid"], ["propanone", "ch3coch3", "one environment"]], "tips": ["IR then NMR."]}]}, "models": {"1": [["Q1", "But-2-ene: cis–trans. Butan-2-ol and lactic acid: optical (chiral C). Propan-1-ol and but-1-ene: neither."]], "2": [["Q2", "O–H alcohol; C=O; O–H acid; CH₃⁺; COOH⁺."]], "3": [["Q3", "3 environments; 3:2:1; CH₃ triplet (2 neighbours on CH₂); CH₂ quartet (3 neighbours on CH₃); OH singlet."], ["Q4", "All six H atoms are in the same chemical environment because the molecule is symmetrical [1]; there are no H atoms on adjacent carbons (the C=O carbon has none), so the signal is a singlet [1]."]], "4": [["Q5", "The absorption at 1720 cm⁻¹ shows a C=O (carbonyl) group [1]; no broad band above 3000 cm⁻¹ means there is no O–H, so it is not an alcohol or acid [1]; a single NMR signal means all H are equivalent, so it is propanone, CH₃COCH₃ [1]."]], "6": [["Exit ticket", "A signal is split into n + 1 peaks by n hydrogen atoms on adjacent carbon atoms."]]}, "labels": {"q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f74e7c93-ab19-502e-a8c9-3a2de1f20311', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R1.1' limit 1), 'R1.1 Measuring enthalpy changes · Lesson 1: System and surroundings, endothermic and exothermic reactions, calorimetry', 'IB DP Chemistry · R1.1 Measuring enthalpy changes', '/chem-r11-lesson1/', 'CHEM-R11-L1', 12, 1 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R11-L1', 'R1.1 Measuring enthalpy changes · Lesson 1: System and surroundings, endothermic and exothermic reactions, calorimetry', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Exothermic", "Endothermic", "Endothermic", "Exothermic", "Endothermic"], "tip": "Sign of ΔH; temperature of surroundings."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["2842", "2840", "2.84"], ["0.0500", "0.05 mol"], ["−56.8", "-56.8", "−57", "-57"]], "tips": ["Q = 100 g × 4.18 × 6.8; n = 0.0500 mol."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["heat loss", "lost to", "surroundings", "air"], ["incomplete combustion", "soot", "can", "calorimeter absorb", "evaporat"]], "tips": ["Where does the energy go?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["lower enthalpy", "lower than", "below"], ["activation energy", "hump", "peak", "ea"]], "tips": ["Relative levels and the hump."]}]}, "models": {"1": [["Q1", "Combustion and neutralization: exothermic. NH₄NO₃ dissolving, decomposition, positive ΔH: endothermic."]], "2": [["Q2", "Q = 100.0 × 4.18 × 6.8 = 2842 J = 2.84 kJ [1]; n(H₂O) = 0.0500 dm³ × 1.00 = 0.0500 mol [1]; ΔH = −2.84 ÷ 0.0500 = −56.8 kJ mol⁻¹ [1]."]], "3": [["Q3", "Much heat is lost to the surrounding air rather than heating the water [1]; incomplete combustion (soot) and heat absorbed by the copper can also reduce the measured temperature rise [1]."]], "4": [["Q4", "The products are at a lower enthalpy than the reactants, with ΔH shown as a downward arrow (negative) [1]; a hump between them shows the activation energy [1]."]], "6": [["Exit ticket", "Q = mcΔT."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd97d1bb8-3c67-5f66-9529-fb13e0033046', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R1.2' limit 1), 'R1.2 Energy cycles in reactions · Lesson 1: Bond enthalpies and Hess''s law', 'IB DP Chemistry · R1.2 Energy cycles in reactions', '/chem-r12-lesson1/', 'CHEM-R12-L1', 6, 11 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R12-L1', 'R1.2 Energy cycles in reactions · Lesson 1: Bond enthalpies and Hess''s law', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["678", "862"], ["−184", "-184"]], "tips": ["Broken − formed."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 1, "pts": [["average", "different compounds", "vary", "gas"]], "tips": ["Where do the values come from?"]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q3", "max": 2, "pts": [["−99", "-99", "halve", "÷ 2", "/2"], ["−396", "-396"]], "tips": ["Halve the second equation, then add."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 1, "pts": [["independent", "route", "pathway", "same"]], "tips": ["Route."]}]}, "models": {"1": [["Q1", "Bonds broken = 436 + 242 = 678; bonds formed = 2 × 431 = 862 [1]; ΔH = 678 − 862 = −184 kJ mol⁻¹ [1]."], ["Q2", "Bond enthalpies are averages taken from many different compounds, so they are not exact for the specific molecules in the reaction (and apply only to gases) [1]."]], "2": [["Q3", "Halve the second equation: SO₂ + ½O₂ → SO₃, ΔH = −99 kJ [1]; add to the first: ΔH = −297 + (−99) = −396 kJ mol⁻¹ [1]."]], "3": [["Q4", "The enthalpy change of a reaction is independent of the pathway taken, depending only on the initial and final states [1]."]], "6": [["Exit ticket", "Endothermic."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_0": "Q3", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '88e08b42-e5ff-55a0-9d42-f0783c1fb933', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R1.2' limit 1), 'R1.2 Energy cycles in reactions · Lesson 2 (HL): Enthalpies of formation and combustion, and Born–Haber cycles', 'IB DP Chemistry · R1.2 Energy cycles in reactions', '/chem-r12-lesson2/', 'CHEM-R12-L2', 8, 12 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R12-L2', 'R1.2 Energy cycles in reactions · Lesson 2 (HL): Enthalpies of formation and combustion, and Born–Haber cycles', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["−966", "-966", "−74"], ["−892", "-892", "−890", "-890"]], "tips": ["Products − reactants; O₂ = 0."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["89 + 419 + 121", "280", "−437", "+437"], ["717", "+717"]], "tips": ["Lattice = sum of steps − ΔH_f."]}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["k+ larger", "larger", "radius"], ["weaker", "attraction", "same charge"]], "tips": ["Ion size."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["1 mol", "one mole"], ["elements", "standard states", "standard conditions"]], "tips": ["Amount and starting materials."]}]}, "models": {"1": [["Q1", "Σ products = −394 + 2(−286) = −966; Σ reactants = −74 [1]; ΔH = −966 − (−74) = −892 kJ mol⁻¹ [1]."]], "2": [["Q2", "ΔH_lattice = 89 + 419 + 121 − 349 − (−437) [1] = +717 kJ mol⁻¹ [1]."], ["Q3", "K⁺ has a larger ionic radius than Na⁺ while the charges are the same [1], so the electrostatic attraction between the ions is weaker [1]."]], "3": [["Q4", "The enthalpy change when one mole of a compound is formed [1] from its elements in their standard states under standard conditions [1]."]], "6": [["Exit ticket", "Zero (it is an element in its standard state)."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q2_1": "Q3", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '418b9bf4-ce09-5180-b56e-2b2adf4875e7', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R1.3' limit 1), 'R1.3 Energy from fuels · Lesson 1: Combustion, incomplete combustion, fossil fuels, biofuels and fuel cells', 'IB DP Chemistry · R1.3 Energy from fuels', '/chem-r13-lesson1/', 'CHEM-R13-L1', 11, 21 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R13-L1', 'R1.3 Energy from fuels · Lesson 1: Combustion, incomplete combustion, fossil fuels, biofuels and fuel cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["5", "2", "CO", "C"], "tip": "Balance C, H then O."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["renewable", "photosynthesis", "carbon neutral", "absorbed"], ["land", "food", "fertiliz", "deforest", "energy to produce", "lower energy"], ["conclusion", "overall", "depends", "only if", "sustainable"]], "tips": ["Benefit, cost, judgement."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["water only", "no co2", "efficient"], ["storage", "expensive", "platinum", "fossil", "production", "infrastructure"]], "tips": ["Emissions vs practicality."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["2ch4 + 3o2", "2co + 4h2o", "ch4 + 1.5o2", "co + 2h2o"], ["toxic", "haemoglobin", "hemoglobin", "oxygen transport"]], "tips": ["Balance; effect of CO."]}]}, "models": {"1": [["Q1", "5; 2; CO; C (soot)."]], "2": [["Q2", "Ethanol is renewable, and the CO₂ released is absorbed by the next crop during photosynthesis, so it is closer to carbon-neutral [1]; however it competes with food crops for land and water and needs energy for fertilizer, harvesting and distillation [1]; it is sustainable only if grown on land not needed for food without causing deforestation [1]."]], "3": [["Q3", "Advantage: the only product is water, so there are no CO₂ or particulate emissions at the vehicle, and efficiency is high [1]; disadvantage: hydrogen is difficult and expensive to store, and is often produced from fossil fuels [1]."]], "4": [["Q4", "2CH₄ + 3O₂ → 2CO + 4H₂O [1]; CO is toxic because it binds to haemoglobin and prevents oxygen transport [1]."]], "6": [["Exit ticket", "Carbon dioxide and water."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '86dbfb7d-5cd6-59e4-85a0-117b0fc7c82d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R1.4' limit 1), 'R1.4 Entropy and spontaneity · Lesson 1 (HL): Entropy, Gibbs energy and spontaneity', 'IB DP Chemistry · R1.4 Entropy and spontaneity', '/chem-r14-lesson1/', 'CHEM-R14-L1', 15, 31 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R14-L1', 'R1.4 Entropy and spontaneity · Lesson 1 (HL): Entropy, Gibbs energy and spontaneity', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Positive", "Negative", "Positive", "Positive", "Negative"], "tip": "Count moles of gas; states."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["0.161", "48"], ["+130", "130"], ["1106", "1100", "1105"]], "tips": ["Convert ΔS to kJ; T = ΔH/ΔS."]}, {"kind": "choice", "id": "q2_1", "q": "Q3", "max": 4, "n": 4, "ans": ["At all temperatures", "At no temperature", "At low temperatures only", "At high temperatures only"], "tip": "Sign of ΔH − TΔS."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 1, "pts": [["equilibrium"]], "tips": ["No driving force."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["δh positive", "endothermic", "ΔH positive", "δs positive", "entropy increase"], ["tδs", "t × δs", "higher temperature", "outweigh", "exceeds"]], "tips": ["Signs of ΔH and ΔS."]}]}, "models": {"1": [["Q1", "Evaporation, decomposition producing gas, dissolving: positive. Fewer gas moles (NH₃, SO₃): negative."]], "2": [["Q2", "ΔG = 178 − 298 × 0.161 = 178 − 48.0 [1] = +130 kJ mol⁻¹ (not spontaneous) [1]; T = 178 ÷ 0.161 = 1106 K [1]."], ["Q3", "All; none; low T; high T."]], "3": [["Q4", "When ΔG = 0 the system is at equilibrium, with no net driving force in either direction [1]."]], "4": [["Q5", "Melting is endothermic (ΔH positive) but entropy increases (ΔS positive) [1]; above 0 °C, TΔS exceeds ΔH so ΔG is negative, while below 0 °C TΔS is smaller than ΔH so ΔG is positive [1]."]], "6": [["Exit ticket", "ΔG = ΔH − TΔS."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '72e4e0da-f700-54c0-86e7-7ebb4c7ef8c5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R2.1' limit 1), 'R2.1 How much? The amount of chemical change · Lesson 1: Equations, reacting quantities, limiting reactants, yield and atom economy', 'IB DP Chemistry · R2.1 How much? The amount of chemical change', '/chem-r21-lesson1/', 'CHEM-R21-L1', 12, 41 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R21-L1', 'R2.1 How much? The amount of chemical change · Lesson 1: Equations, reacting quantities, limiting reactants, yield and atom economy', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["0.250", "0.25 mol"], ["11.0", "11 g"]], "tips": ["1 : 1 ratio."]}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["0.00200", "0.002", "0.00400", "0.004"], ["0.160", "0.16"]], "tips": ["2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 3, "n": 3, "ans": ["N₂", "1.43 mol", "24.3 g"], "tip": "N₂: 0.714 ÷ 1; H₂: 2.48 ÷ 3 = 0.825."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 1, "pts": [["74.9", "75"]], "tips": ["Experimental ÷ theoretical × 100."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q5", "max": 2, "pts": [["30.03", "30.0", "2.02 ÷"], ["6.7", "6.73", "6.72"]], "tips": ["Desired product ÷ total reactants."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["yield+actual", "yield+experimental", "yield+obtained"], ["atom economy+reactants", "atom economy+equation", "atom economy+desired", "atom economy+waste"]], "tips": ["Experiment vs equation."]}]}, "models": {"1": [["Q1", "n(CaCO₃) = 25.0 ÷ 100.09 = 0.250 mol = n(CO₂) [1]; mass = 0.250 × 44.01 = 11.0 g [1]."], ["Q2", "n(H₂SO₄) = 0.0200 × 0.100 = 0.00200 mol, so n(NaOH) = 0.00400 mol [1]; c = 0.00400 ÷ 0.0250 = 0.160 mol dm⁻³ [1]."]], "2": [["Q3", "N₂ is limiting (0.714 < 0.825); n(NH₃) = 2 × 0.714 = 1.43 mol; mass = 1.43 × 17.04 = 24.3 g."], ["Q4", "18.2 ÷ 24.3 × 100 = 74.9% [1]."]], "3": [["Q5", "Total mass of reactants = 12.01 + 18.02 = 30.03 [1]; atom economy = 2.02 ÷ 30.03 × 100 = 6.73% [1]."]], "4": [["Q6", "Percentage yield compares the amount of product actually obtained with the theoretical maximum [1]; atom economy is calculated from the equation and shows what proportion of reactant atoms end up in the desired product [1]."]], "6": [["Exit ticket", "Divide moles of each reactant by its coefficient; the smallest value is limiting."]]}, "labels": {"q1_0": "Q1", "q1_1": "Q2", "q2_1": "Q4", "q3_0": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '1e139769-6dd6-537f-81b4-57a880229ca5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R2.2' limit 1), 'R2.2 How fast? The rate of chemical change · Lesson 1: Rate, collision theory, factors affecting rate, activation energy and catalysts', 'IB DP Chemistry · R2.2 How fast? The rate of chemical change', '/chem-r22-lesson1/', 'CHEM-R22-L1', 13, 51 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R22-L1', 'R2.2 How fast? The rate of chemical change · Lesson 1: Rate, collision theory, factors affecting rate, activation energy and catalysts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Gas syringe", "Mass loss on a balance", "Time for a cross to disappear", "Colorimeter"], "tip": "What changes that you can measure?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["kinetic energy", "faster", "move"], ["activation energy", "e ≥ ea", "more particles have", "proportion"], ["successful", "frequent", "more collisions"]], "tips": ["Energy and frequency."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Decreases", "No change", "Increases", "Increases"], "tip": "Alternative pathway."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["surface area"], ["more frequent", "more collisions", "exposed"]], "tips": ["Surface area."]}]}, "models": {"1": [["Q1", "Gas syringe; mass loss; cross; colorimeter."]], "2": [["Q2", "At higher temperature particles have more kinetic energy and move faster [1]; a greater proportion of particles have energy equal to or greater than the activation energy [1]; so there are more frequent successful collisions per unit time [1]."]], "3": [["Q3", "Ea decreases; ΔH unchanged; rate increases; more particles have enough energy."]], "4": [["Q4", "Powder has a larger surface area [1], so more particles are exposed and there are more frequent collisions with acid particles per unit time [1]."]], "6": [["Exit ticket", "Energy at least equal to the activation energy, and the correct orientation."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'fa989833-686f-5da3-85a1-e454c4772d83', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R2.2' limit 1), 'R2.2 How fast? The rate of chemical change · Lesson 2 (HL): Mechanisms, rate equations, orders, rate constants and the Arrhenius equation', 'IB DP Chemistry · R2.2 How fast? The rate of chemical change', '/chem-r22-lesson2/', 'CHEM-R22-L2', 14, 52 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R22-L2', 'R2.2 How fast? The rate of chemical change · Lesson 2 (HL): Mechanisms, rate equations, orders, rate constants and the Arrhenius equation', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["NO₃", "Step 1", "Bimolecular"], "tip": "Made then used = intermediate."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["1", "2", "3", "rate = k[A][B]²", "2.0 dm⁶ mol⁻² s⁻¹"], "tip": "Compare pairs of experiments."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["half-life", "half life"], ["constant", "same", "independent"]], "tips": ["Half-life."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["6000 × 8.31", "−gradient", "49860", "49 860"], ["49.9", "50"]], "tips": ["Ea = −gradient × R."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["k[no2]2", "k[no2]²", "[no2]^2", "second order in no2"], ["slow", "rate-determining", "rds"]], "tips": ["Species in the slow step."]}]}, "models": {"1": [["Q1", "NO₃ is the intermediate; step 1 (slow) is rate-determining; step 1 is bimolecular."]], "2": [["Q2", "A doubles → rate doubles: first. B doubles → rate ×4: second. Overall 3. k = 2.0 × 10⁻³ ÷ (0.10 × 0.10²) = 2.0 dm⁶ mol⁻² s⁻¹."], ["Q3", "Measure successive half-lives from the graph [1]; for a first-order reaction the half-life is constant, independent of concentration [1]."]], "3": [["Q4", "Ea = −(−6000) × 8.31 = 49 860 J mol⁻¹ [1] = 49.9 kJ mol⁻¹ [1]."]], "4": [["Q5", "Rate = k[NO₂]² [1], because the slow, rate-determining step involves two NO₂ molecules and CO is not involved until after the RDS [1]."]], "6": [["Exit ticket", "dm³ mol⁻¹ s⁻¹."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '2d2d99f6-732c-54c7-a1c0-0cec3a139ae3', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R2.3' limit 1), 'R2.3 How far? The extent of chemical change · Lesson 1: Dynamic equilibrium, the equilibrium constant and Le Châtelier''s principle', 'IB DP Chemistry · R2.3 How far? The extent of chemical change', '/chem-r23-lesson1/', 'CHEM-R23-L1', 14, 61 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R23-L1', 'R2.3 How far? The extent of chemical change · Lesson 1: Dynamic equilibrium, the equilibrium constant and Le Châtelier''s principle', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["rate", "equal"], ["concentration", "constant", "closed", "both directions"]], "tips": ["Rates and concentrations."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["[NH₃]² / [N₂][H₂]³", "Products", "1/K"], "tip": "Products over reactants, powers = coefficients."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Increases", "Decreases", "No change", "Increases", "Decreases"], "tip": "Oppose the change."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["rate", "slow", "faster"], ["compromise", "yield", "acceptable"]], "tips": ["Rate vs yield."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["both", "forward and backward", "equally"], ["no shift", "same position", "faster", "reached sooner"]], "tips": ["Both directions."]}]}, "models": {"1": [["Q1", "The rates of the forward and backward reactions are equal [1]; the concentrations of reactants and products remain constant in a closed system [1]."]], "2": [["Q2", "K = [NH₃]²/[N₂][H₂]³; large K favours products; reverse K'' = 1/K."]], "3": [["Q3", "Pressure ↑ yield (fewer gas moles on right); temperature ↑ shifts left (endothermic direction) so yield and K decrease; catalyst no change; removing NH₃ increases yield."], ["Q4", "At lower temperatures the rate of reaction would be too slow [1]; 450 °C is a compromise giving an acceptable yield at a reasonable rate (with a catalyst) [1]."]], "4": [["Q5", "A catalyst increases the rates of the forward and backward reactions equally [1], so equilibrium is reached faster but its position (and K) is unchanged [1]."]], "6": [["Exit ticket", "Temperature."]]}, "labels": {"q1_0": "Q1", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'ab4dbfe5-5496-57a6-9ba9-baa625253ec6', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R2.3' limit 1), 'R2.3 How far? The extent of chemical change · Lesson 2 (HL): Reaction quotient, equilibrium calculations and ΔG', 'IB DP Chemistry · R2.3 How far? The extent of chemical change', '/chem-r23-lesson2/', 'CHEM-R23-L2', 10, 62 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R23-L2', 'R2.3 How far? The extent of chemical change · Lesson 2 (HL): Reaction quotient, equilibrium calculations and ΔG', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 3, "n": 3, "ans": ["Forwards (to the right)", "Backwards (to the left)", "At equilibrium"], "tip": "Q heads towards K."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["0.39"], ["0.11"], ["50", "50.3", "50.28"]], "tips": ["x = 0.39."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["9.21", "ln k", "ln(1.0", "ln (1"], ["−22.8", "-22.8", "−23", "-23", "−22 8"]], "tips": ["ΔG = −RT ln K."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["too many products", "products", "more product"], ["backward", "left", "reverse", "decreases"]], "tips": ["Compare to equilibrium."]}]}, "models": {"1": [["Q1", "Q < K → forwards; Q > K → backwards; Q = K → equilibrium."]], "2": [["Q2", "Change in H₂ and I₂ = 0.78 ÷ 2 = 0.39 [1]; equilibrium [H₂] = [I₂] = 0.50 − 0.39 = 0.11 [1]; K = 0.78² ÷ (0.11 × 0.11) = 50 [1]."]], "3": [["Q3", "ln K = ln(1.0 × 10⁴) = 9.21 [1]; ΔG⦵ = −8.31 × 298 × 9.21 = −22 800 J mol⁻¹ = −22.8 kJ mol⁻¹ [1]."]], "4": [["Q4", "When Q > K there are relatively more products than at equilibrium [1], so the reverse reaction is favoured and the mixture shifts to the left until Q = K [1]."]], "6": [["Exit ticket", "Greater than 1."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6c017e99-424d-5c7e-a67b-878b6cb8e3b0', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.1' limit 1), 'R3.1 Proton transfer reactions · Lesson 1: Brønsted–Lowry acids and bases, pH, Kw, strong and weak acids, neutralization and pH curves', 'IB DP Chemistry · R3.1 Proton transfer reactions', '/chem-r31-lesson1/', 'CHEM-R31-L1', 17, 71 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R31-L1', 'R3.1 Proton transfer reactions · Lesson 1: Brønsted–Lowry acids and bases, pH, Kw, strong and weak acids, neutralization and pH curves', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["H₂O", "NH₃", "NH₄⁺", "OH⁻"], "tip": "Who donates H⁺?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["2.0", "1.0 × 10⁻⁵ mol dm⁻³", "12.0", "1.0 × 10⁻¹² mol dm⁻³", "100 times"], "tip": "[H⁺] = Kw/[OH⁻]."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["ph", "lower ph"], ["conductiv", "rate", "magnesium", "bubbles", "faster"]], "tips": ["pH, conductivity, rate."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["MgSO₄ + H₂O", "CaCl₂ + H₂O + CO₂", "NaNO₃ + H₂O", "KCl + H₂O + CO₂"], "tip": "Carbonates give CO₂."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["strong+complete", "strong+fully"], ["weak+partial", "weak+equilibrium"]], "tips": ["Extent of ionization."]}]}, "models": {"1": [["Q1", "H₂O donates H⁺ (acid); NH₃ accepts (base); NH₄⁺ is the conjugate acid of NH₃; OH⁻ is the conjugate base of H₂O."]], "2": [["Q2", "pH 2.0; 1.0 × 10⁻⁵; [H⁺] = 10⁻¹⁴/0.010 = 10⁻¹² so pH 12.0; 100 times."]], "3": [["Q3", "Measure pH: HCl has a lower pH (higher [H⁺]) [1]; measure conductivity or add magnesium: HCl conducts better and reacts faster, producing bubbles more quickly [1]."]], "4": [["Q4", "MgSO₄ + H₂O; CaCl₂ + H₂O + CO₂; NaNO₃ + H₂O; KCl + H₂O + CO₂."]], "5": [["Q5", "A strong acid ionizes completely in water [1]; a weak acid ionizes only partially, establishing an equilibrium [1]."]], "6": [["Exit ticket", "Conjugate base CO₃²⁻; conjugate acid H₂CO₃."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '051c5895-50c9-5f40-8d44-063429a3987f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.1' limit 1), 'R3.1 Proton transfer reactions · Lesson 2 (HL): pOH, Ka and Kb, salt hydrolysis, pH curves, indicators and buffers', 'IB DP Chemistry · R3.1 Proton transfer reactions', '/chem-r31-lesson2/', 'CHEM-R31-L2', 19, 72 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R31-L2', 'R3.1 Proton transfer reactions · Lesson 2 (HL): pOH, Ka and Kb, salt hydrolysis, pH curves, indicators and buffers', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["1.3 × 10⁻³", "1.34", "1.3e-3", "1.3 x 10", "√(1.8"], ["2.87", "2.9"]], "tips": ["[H⁺] = √(Ka c)."]}, {"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["11.0", "9.25", "5.6 × 10⁻¹⁰"], "tip": "pH + pOH = 14; Ka × Kb = Kw."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["= 7", "> 7", "< 7", "< 7", "> 7"], "tip": "The salt formed decides."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Phenolphthalein", "Methyl orange", "Either", "Neither suitable"], "tip": "Match range to the jump."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["oh⁻", "oh-", "hydroxide"], ["ch3cooh", "ethanoic acid", "reacts", "removed", "neutralized"]], "tips": ["Which component reacts with OH⁻?"]}, {"kind": "text", "id": "q4_1", "q": "Q6", "max": 1, "pts": [["4.46", "4.5"]], "tips": ["pH = pKa + log(salt/acid)."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 2, "pts": [["half", "half-equivalence", "half the volume"], ["[ha] = [a", "equal", "ph = pka"]], "tips": ["Halfway to equivalence."]}]}, "models": {"1": [["Q1", "[H⁺] = √(1.8 × 10⁻⁵ × 0.10) = 1.34 × 10⁻³ mol dm⁻³ [1]; pH = −log(1.34 × 10⁻³) = 2.87 [1]."], ["Q2", "pOH 11.0; pKb = 14 − 4.75 = 9.25; Kb = 10⁻¹⁴ ÷ 1.8 × 10⁻⁵ = 5.6 × 10⁻¹⁰."]], "2": [["Q3", "= 7; > 7; < 7; < 7; > 7."]], "3": [["Q4", "Phenolphthalein; methyl orange; either; neither (no sharp jump)."]], "4": [["Q5", "The added OH⁻ ions react with ethanoic acid: CH₃COOH + OH⁻ → CH₃COO⁻ + H₂O [1], so the OH⁻ is removed and the ratio of acid to salt changes only slightly, keeping pH nearly constant [1]."], ["Q6", "pH = 4.76 + log(0.10/0.20) = 4.76 − 0.30 = 4.46 [1]."]], "5": [["Q7", "Read the pH at half the volume of NaOH needed to reach the equivalence point (half-equivalence) [1]; here [HA] = [A⁻], so pH = pKa [1]."]], "6": [["Exit ticket", "Ka × Kb = Kw."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q5", "q4_1": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '53ae0348-af43-5ad6-829f-9afb5635add8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 1: Redox, half-equations, reactivity, metals with acids, and electrochemical cells', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson1/', 'CHEM-R32-L1', 20, 81 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L1', 'R3.2 Electron transfer reactions · Lesson 1: Redox, half-equations, reactivity, metals with acids, and electrochemical cells', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Zn", "Cu²⁺", "Cu²⁺", "Zn", "SO₄²⁻"], "tip": "Follow electrons."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["14h", "14 h", "7h2o", "7 h2o", "7h₂o"], ["6e", "6 e"]], "tips": ["O → H₂O, then H⁺, then e⁻."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Reaction", "No reaction", "Reaction", "No reaction"], "tip": "Activity series."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Voltaic cell", "Electrolytic cell", "Both", "Voltaic cell", "Electrolytic cell"], "tip": "Spontaneous or driven?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["pb", "lead", "cathode"], ["br2", "bromine", "anode"]], "tips": ["Cations to cathode, anions to anode."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 2, "pts": [["ions", "move", "flow"], ["complete", "circuit", "neutral", "balance charge"]], "tips": ["Ions and charge."]}]}, "models": {"1": [["Q1", "Zn oxidized (reducing agent); Cu²⁺ reduced (oxidizing agent); SO₄²⁻ spectator."], ["Q2", "Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O: balancing O with 7H₂O and H with 14H⁺ [1]; 6e⁻ to balance charge [1]."]], "2": [["Q3", "Mg displaces Cu: reaction. Cu cannot displace Zn. Zn + HCl gives H₂. Ag is below H: no reaction."]], "3": [["Q4", "Chemical→electrical, anode negative: voltaic. Power supply, Al extraction: electrolytic. Oxidation at anode: both."], ["Q5", "Cathode: Pb²⁺ + 2e⁻ → Pb (lead) [1]; anode: 2Br⁻ → Br₂ + 2e⁻ (bromine) [1]."]], "4": [["Q6", "The salt bridge allows ions to move between the two half-cells [1], completing the circuit and keeping each solution electrically neutral [1]."]], "6": [["Exit ticket", "The anode."]]}, "labels": {"q1_1": "Q2", "q3_1": "Q5", "q4_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '9f53fff7-476f-5d75-9958-a9821413b8e1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 2: Redox in organic chemistry: oxidation of alcohols and reduction', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson2/', 'CHEM-R32-L2', 12, 82 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L2', 'R3.2 Electron transfer reactions · Lesson 2: Redox in organic chemistry: oxidation of alcohols and reduction', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ethanal", "Ethanoic acid", "Propanone", "No reaction"], "tip": "Primary, secondary, tertiary."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 2, "pts": [["boiling point", "low", "volatile", "evaporat"], ["removed", "further oxidation", "carboxylic acid", "before"]], "tips": ["Prevent the next step."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Ethanol", "Propan-2-ol", "Ethane", "Butan-1-ol"], "tip": "Reverse of oxidation."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["dichromate", "k2cr2o7", "acidified"], ["orange", "green", "no change", "stays orange"]], "tips": ["Which can be oxidized?"]}]}, "models": {"1": [["Q1", "Ethanal; ethanoic acid; propanone; no reaction (tertiary)."], ["Q2", "The aldehyde has a lower boiling point than the alcohol and evaporates as it forms [1], so distilling removes it before it can be further oxidized to a carboxylic acid [1]."]], "2": [["Q3", "Ethanol; propan-2-ol; ethane; butan-1-ol."]], "3": [["Q4", "Warm each with acidified potassium dichromate(VI) [1]; propan-1-ol turns it from orange to green, while the tertiary alcohol 2-methylpropan-2-ol leaves it orange [1]."]], "6": [["Exit ticket", "A ketone."]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f6f0a6e0-8a7c-5514-9bff-1b0d7c63a31f', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.2' limit 1), 'R3.2 Electron transfer reactions · Lesson 3 (HL): Standard electrode potentials, cell potentials, ΔG, electrolysis of solutions and electroplating', 'IB DP Chemistry · R3.2 Electron transfer reactions', '/chem-r32-lesson3/', 'CHEM-R32-L3', 15, 83 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R32-L3', 'R3.2 Electron transfer reactions · Lesson 3 (HL): Standard electrode potentials, cell potentials, ΔG, electrolysis of solutions and electroplating', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["+0.46 V", "+1.25 V", "Ag⁺", "Mg", "No"], "tip": "E(cathode) − E(anode)."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["2 × 96", "212 300", "212300", "96 500", "96500"], ["−212", "-212"]], "tips": ["ΔG = −nFE."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["H₂ and O₂", "H₂ and Cl₂", "Cu and O₂", "Na and Cl₂"], "tip": "Compare E⦵ with water; concentration of halide."}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 2, "pts": [["spoon+cathode", "cathode"], ["silver anode", "ag+", "silver nitrate", "silver ions"]], "tips": ["Which electrode is the spoon?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["water", "h2o", "hydrogen"], ["more positive", "easier", "e⦵", "reduced preferentially", "−2.71"]], "tips": ["Compare reductions."]}]}, "models": {"1": [["Q1", "Cu/Ag +0.46 V; Fe/Ag +1.25 V; Ag⁺ strongest oxidizer; Mg strongest reducer; Cu + Fe²⁺: E = −0.45 − 0.34 = −0.79 V, not spontaneous."]], "2": [["Q2", "ΔG⦵ = −2 × 96 500 × 1.10 = −212 300 J mol⁻¹ [1] = −212 kJ mol⁻¹ [1]."]], "3": [["Q3", "H₂ + O₂; H₂ + Cl₂; Cu + O₂; Na + Cl₂."], ["Q4", "Make the spoon the cathode and a piece of silver the anode [1], in an electrolyte containing Ag⁺ ions such as silver nitrate solution [1]."]], "4": [["Q5", "Water is reduced to hydrogen instead [1], because water has a more positive (less negative) reduction potential than Na⁺, so it is reduced preferentially [1]."]], "6": [["Exit ticket", "Positive."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '54e73dfb-862d-5617-97a8-c883409797c1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.3' limit 1), 'R3.3 Electron sharing reactions · Lesson 1: Radicals, homolytic fission and free-radical substitution', 'IB DP Chemistry · R3.3 Electron sharing reactions', '/chem-r33-lesson1/', 'CHEM-R33-L1', 9, 91 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R33-L1', 'R3.3 Electron sharing reactions · Lesson 1: Radicals, homolytic fission and free-radical substitution', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 2, "pts": [["uv", "ultraviolet", "light"], ["one electron each", "each atom", "two radicals", "2cl•", "each chlorine"]], "tips": ["Conditions and result."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Initiation", "Propagation", "Termination", "Propagation", "Termination"], "tip": "Radicals made, kept, or removed?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["further substitution", "ch2cl2", "chcl3", "more"], ["radical", "cl•", "random", "react with chloromethane"]], "tips": ["Chloromethane can react too."]}]}, "models": {"1": [["Q1", "In UV light the Cl–Cl bond breaks [1], with each chlorine atom keeping one electron of the shared pair, forming two chlorine radicals: Cl₂ → 2Cl• [1]."]], "2": [["Q2", "Initiation; propagation; termination; propagation; termination."]], "3": [["Q3", "Chlorine radicals can also react with chloromethane and other products, so further substitution occurs giving CH₂Cl₂, CHCl₃ and CCl₄ [1]; termination steps also produce ethane, so a mixture forms [1]."]], "6": [["Exit ticket", "Initiation, propagation and termination."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '93e1de9d-63e2-5115-bc65-8416403a742c', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.4' limit 1), 'R3.4 Electron-pair sharing reactions · Lesson 1: Nucleophiles, electrophiles, heterolytic fission, substitution and electrophilic addition', 'IB DP Chemistry · R3.4 Electron-pair sharing reactions', '/chem-r34-lesson1/', 'CHEM-R34-L1', 13, 101 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R34-L1', 'R3.4 Electron-pair sharing reactions · Lesson 1: Nucleophiles, electrophiles, heterolytic fission, substitution and electrophilic addition', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Nucleophile", "Nucleophile", "Not a nucleophile", "Nucleophile", "Not a nucleophile"], "tip": "Lone pair to donate?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["1,2-dibromoethane", "Bromoethane", "Ethanol", "Ethane"], "tip": "Add across C=C."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["electron density", "electron-rich", "pi", "π", "double bond"], ["attract", "electrophile"]], "tips": ["What does the double bond provide?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["bromine water"], ["colourless", "decolor", "decolour", "stays orange", "remains"]], "tips": ["Unsaturation test."]}]}, "models": {"1": [["Q1", "OH⁻, NH₃, CN⁻: nucleophiles. H⁺ (no electrons) and CH₄ (no lone pair): not."]], "2": [["Q2", "1,2-dibromoethane; bromoethane; ethanol; ethane."], ["Q3", "The C=C double bond (with its π bond) is a region of high electron density [1], which attracts electrophiles (electron-pair acceptors), so addition occurs [1]."]], "3": [["Q4", "Add bromine water to each [1]; hex-1-ene decolourizes it (orange to colourless), while hexane leaves it orange [1]."]], "6": [["Exit ticket", "A species that accepts a pair of electrons to form a new bond."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '92789f81-e6fc-549b-87ed-8d44578d7af5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Diploma Chemistry' and t.code = 'R3.4' limit 1), 'R3.4 Electron-pair sharing reactions · Lesson 2 (HL): Lewis acids and bases, complex ions, SN1 and SN2, addition mechanisms and Markovnikov', 'IB DP Chemistry · R3.4 Electron-pair sharing reactions', '/chem-r34-lesson2/', 'CHEM-R34-L2', 17, 102 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CHEM-R34-L2', 'R3.4 Electron-pair sharing reactions · Lesson 2 (HL): Lewis acids and bases, complex ions, SN1 and SN2, addition mechanisms and Markovnikov', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Lewis acid", "Lewis base", "Lewis acid", "Lewis base", "Lewis base"], "tip": "Accepts or donates an electron pair?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["SN2", "SN1", "SN2", "SN1", "SN2"], "tip": "Primary vs tertiary; one step vs two."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 2, "pts": [["c–i", "c-i", "weaker", "bond enthalpy"], ["leaving group", "breaks more easily", "easier"]], "tips": ["Bond strength."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["carbocation"], ["secondary", "more stable"], ["inductive", "alkyl", "electron-releasing", "methyl"]], "tips": ["Which carbocation forms?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 2, "pts": [["steric", "hindrance", "bulky", "blocked"], ["carbocation", "stable", "inductive"]], "tips": ["Two reasons."]}]}, "models": {"1": [["Q1", "BF₃ and Fe³⁺: acids. NH₃, Cl⁻, H₂O ligand: bases."]], "2": [["Q2", "Bromoethane: SN2; tertiary: SN1; bimolecular rate: SN2; carbocation: SN1; inversion: SN2."], ["Q3", "The C–I bond is weaker (lower bond enthalpy) than the C–Cl bond [1], so iodide is a better leaving group and the bond breaks more easily [1]."]], "3": [["Q4", "The reaction proceeds via a carbocation intermediate [1]; adding H⁺ to the terminal carbon gives a secondary carbocation, which is more stable than the primary one [1], because the two alkyl groups release electrons (positive inductive effect) and stabilize the positive charge [1]."]], "4": [["Q5", "Bulky alkyl groups cause steric hindrance, blocking backside attack by the nucleophile (SN2) [1]; the tertiary carbocation formed in SN1 is stabilized by the positive inductive effect of three alkyl groups [1]."]], "6": [["Exit ticket", "When HX adds to an unsymmetrical alkene, H adds to the carbon with more H atoms, via the more stable carbocation."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
